const config = $('Configuration').first().json;
const files = $input.first().json;

// Handle array response
const fileList = Array.isArray(files) ? files : [];

// Categorize files
const codeFiles = [];
const docFiles = [];
const configFiles = [];

for (const file of fileList) {
  const path = file.filename || '';
  const ext = path.split('.').pop()?.toLowerCase() || '';

  if (path.startsWith('docs/') || path.endsWith('.md') || path.endsWith('.rst')) {
    docFiles.push({ path, status: file.status, changes: file.changes });
  } else if (['py', 'js', 'ts', 'jsx', 'tsx', 'java', 'go', 'rs'].includes(ext)) {
    codeFiles.push({ path, status: file.status, changes: file.changes, patch: file.patch?.slice(0, 500) });
  } else if (['json', 'yaml', 'yml', 'toml', 'ini', 'env'].includes(ext) || path.includes('config')) {
    configFiles.push({ path, status: file.status, changes: file.changes });
  }
}

return {
  ...config,
  total_files: fileList.length,
  code_files: codeFiles,
  doc_files: docFiles,
  config_files: configFiles,
  code_changed: codeFiles.length > 0,
  docs_included: docFiles.length > 0,
  summary: `${codeFiles.length} code, ${docFiles.length} docs, ${configFiles.length} config files`
};

