=Analyze this Pull Request for documentation impact.

PR Title: {{ $json.pr_title }}
PR Author: {{ $json.pr_author }}

Code files changed ({{ $json.code_files.length }}):
{{ $json.code_files.map(f => '- ' + f.path + ' (' + f.status + ', ' + f.changes + ' changes)').join('\n') || 'None' }}

Doc files changed ({{ $json.doc_files.length }}):
{{ $json.doc_files.map(f => '- ' + f.path + ' (' + f.status + ')').join('\n') || 'None' }}

Config files changed ({{ $json.config_files.length }}):
{{ $json.config_files.map(f => '- ' + f.path).join('\n') || 'None' }}

Code patches (truncated):
{{ $json.code_files.slice(0, 3).map(f => '### ' + f.path + '\n```\n' + (f.patch || 'No patch available') + '\n```').join('\n\n') }}

Respond with JSON only:
{
  "needs_doc_update": true/false,
  "confidence": 0.0-1.0,
  "affected_docs": ["list of docs that may need updates"],
  "suggestions": ["specific suggestions for documentation"],
  "summary": "brief explanation"
}

parameters.jsCode:
const config = $('Analyze Files').first().json;
const response = $input.first().json;
const text = response.output || response.text || JSON.stringify(response);

let analysis;
try {
  const jsonMatch = text.match(/```json\n?([\s\S]*?)\n?```/) || text.match(/\{[\s\S]*\}/);
  analysis = JSON.parse(jsonMatch ? (jsonMatch[1] || jsonMatch[0]) : text);
} catch (e) {
  analysis = {
    needs_doc_update: false,
    confidence: 0.3,
    affected_docs: [],
    suggestions: [],
    summary: 'Could not parse AI response'
  };
}

return {
  ...config,
  needs_doc_update: analysis.needs_doc_update === true,
  confidence: analysis.confidence || 0.5,
  affected_docs: analysis.affected_docs || [],
  suggestions: analysis.suggestions || [],
  ai_summary: analysis.summary || 'Analysis complete'
};

